1	package txsaga
2	
3	import (
4		"context"
5		"strings"
6		"sync"
7		"time"
8	)
9	
10	// ValidateDefinition 校验 Saga 定义，非法时返回 ErrInvalidDefinition（可 errors.Is）。
11	// 规则：名称非空、至少一个步骤、每个步骤名非空且不重复、每个步骤都提供正向
12	// 动作；任一动作/补偿的重试最大总调用次数为负、失败等待时长为负同样非法。
13	// 未配置的重试预算按最大 1 次、等待 0 处理。
14	// 步骤声明的前置（DependsOn）必须指向定义内已存在的其它步骤：前置名称未知、
15	// 自依赖、同一前置重复声明或前置关系成环均属非法定义。
16	func ValidateDefinition(d Definition) error {
17		if strings.TrimSpace(d.Name) == "" {
18			return ErrInvalidDefinition
19		}
20		if len(d.Steps) == 0 {
21			return ErrInvalidDefinition
22		}
23		seen := make(map[string]struct{}, len(d.Steps))
24		for _, st := range d.Steps {
25			if strings.TrimSpace(st.Name) == "" || st.Action == nil {
26				return ErrInvalidDefinition
27			}
28			if _, dup := seen[st.Name]; dup {
29				return ErrInvalidDefinition
30			}
31			if st.ActionRetry.MaxAttempts < 0 || st.ActionRetry.RetryWait < 0 ||
32				st.CompensateRetry.MaxAttempts < 0 || st.CompensateRetry.RetryWait < 0 {
33				return ErrInvalidDefinition
34			}
35			seen[st.Name] = struct{}{}
36		}
37		return validateDeps(d.Steps)
38	}
39	
40	// validateDeps 校验各步骤声明的前置关系：前置必须存在、不得自依赖、不得重复，
41	// 且前置关系不得成环。
42	func validateDeps(steps []Step) error {
43		index := make(map[string]int, len(steps))
44		for i, st := range steps {
45			index[st.Name] = i
46		}
47		deps := make([][]int, len(steps))
48		for i, st := range steps {
49			dup := make(map[string]struct{}, len(st.DependsOn))
50			for _, dep := range st.DependsOn {
51				if dep == st.Name {
52					return ErrInvalidDefinition // 自依赖
53				}
54				j, ok := index[dep]
55				if !ok {
56					return ErrInvalidDefinition // 前置未知
57				}
58				if _, exists := dup[dep]; exists {
59					return ErrInvalidDefinition // 重复前置
60				}
61				dup[dep] = struct{}{}
62				deps[i] = append(deps[i], j)
63			}
64		}
65		// 三色 DFS 检测环：灰色表示当前递归栈上，再次遇到即成环。
66		const (
67			white = iota // 未访问
68			gray         // 递归栈上
69			black        // 已完成
70		)
71		color := make([]int, len(steps))
72		var cyclic func(i int) bool
73		cyclic = func(i int) bool {
74			color[i] = gray
75			for _, j := range deps[i] {
76				if color[j] == gray || (color[j] == white && cyclic(j)) {
77					return true
78				}
79			}
80			color[i] = black
81			return false
82		}
83		for i := range steps {
84			if color[i] == white && cyclic(i) {
85				return ErrInvalidDefinition
86			}
87		}
88		return nil
89	}
90	
91	// Engine 在给定 Store 上执行 Saga。零值不可用，请用 NewEngine 创建。
92	type Engine struct {
93		store Store
94	
95		// 同执行身份的进程内串行化，避免并发调用重复进入同一未确认动作。
96		locksMu sync.Mutex
97		locks   map[string]*sync.Mutex
98	
99		// now 为可注入时钟；生产使用 time.Now。
100		now func() time.Time
101	}
102	
103	// NewEngine 创建基于 store 的编排引擎。
104	func NewEngine(store Store) *Engine {
105		return &Engine{store: store, locks: make(map[string]*sync.Mutex), now: time.Now}
106	}
107	
108	func (e *Engine) identityLock(businessKey, idempotencyKey string) *sync.Mutex {
109		key := businessKey + "\x00" + idempotencyKey
110		e.locksMu.Lock()
111		m, ok := e.locks[key]
112		if !ok {
113			m = &sync.Mutex{}
114			e.locks[key] = m
115		}
116		e.locksMu.Unlock()
117		return m
118	}
119	
120	type execView struct {
121		state   *ExecutionState
122		payload any
123	}
124	
125	func (v execView) BusinessKey() string    { return v.state.BusinessKey }
126	func (v execView) SagaName() string       { return v.state.SagaName }
127	func (v execView) IdempotencyKey() string { return v.state.IdempotencyKey }
128	func (v execView) Payload() any           { return v.payload }
129	
130	func (v execView) SucceededSteps() []string {
131		return succeededNames(v.state)
132	}
133	
134	// Execute 按 Definition 执行一次 Saga 请求。
135	//
136	// 执行身份由业务键、Saga 定义与外部幂等键共同确定：
137	//   - 新身份：创建执行并执行未完成步骤；
138	//   - 同身份重试：不重复执行已确认成功的正向步骤或补偿步骤；
139	//     结果未确认的步骤允许被重新调用，重入次数累计在对应步骤的 Attempts，
140	//     动作自身须遵守幂等契约；
141	//   - 已到达终态：直接返回固定的终态结果，不再调用任何动作，也不再追加事件；
142	//   - 同业务键绑定不同定义：返回 ErrDefinitionConflict；
143	//   - 非法定义或缺失业务键/幂等键：返回 ErrInvalidDefinition。
144	//
145	// 调度分两种模式：定义中所有步骤都未声明前置（DependsOn 为空）时按 Steps
146	// 声明顺序逐个执行；任一步骤声明前置后进入依赖图模式——步骤在其全部前置
147	// 确认成功后才启动，无前置的步骤同时启动、并发执行，某一步确认后立即调度
148	// 因此就绪的后续步骤。任一正向动作预算耗尽仍失败时，停止调度未启动步骤，
149	// 已启动的兄弟动作继续运行到返回并各自原子提交结果，随后仅按确认成功顺序
150	// 的逆序补偿已确认成功的步骤；未执行到或未确认的步骤不补偿。
151	//
152	// 每一步确认后，状态与对应 Outbox 事件在同一个 Store 事务中原子提交，
153	// 然后才调度后续步骤。正向动作在其 ActionRetry 预算内的失败会在指定等待后
154	// 重试同一动作，中间失败不提交状态、不追加事件；预算耗尽仍失败才停止推进。
155	// 动作返回 Permanent 包装的永久失败时即使预算尚有剩余也只调用一次、不再
156	// 等待，按预算耗尽的同一口径提交失败。补偿动作同样可配置 CompensateRetry
157	// 预算，预算耗尽仍报错或返回永久失败则固定为 compensation_failed 终态。
158	// 重试等待与动作本身都响应 ctx：ctx 取消时（即使动作刚返回永久失败）
159	// Execute 返回 ctx 的错误，不确认当前动作、不调度新的兄弟步骤、不启动补偿，
160	// 也不改变已经提交的执行状态。
161	func (e *Engine) Execute(ctx context.Context, def Definition, req ExecutionRequest) (Result, error) {
162		if err := ValidateDefinition(def); err != nil {
163			return Result{}, err
164		}
165		if strings.TrimSpace(req.BusinessKey) == "" || strings.TrimSpace(req.IdempotencyKey) == "" {
166			return Result{}, ErrInvalidDefinition
167		}
168		fp := fingerprint(def)
169	
170		mu := e.identityLock(req.BusinessKey, req.IdempotencyKey)
171		mu.Lock()
172		defer mu.Unlock()
173	
174		for {
175			if err := ctx.Err(); err != nil {
176				return Result{}, err
177			}
178			snap, err := e.store.LoadSnapshot(ctx, req.BusinessKey, req.IdempotencyKey)
179			if err != nil {
180				return Result{}, err
181			}
182			if snap.Bound && snap.Binding.Fingerprint != fp {
183				return Result{}, ErrDefinitionConflict
184			}
185			st := snap.State
186			if st == nil {
187				if err := e.createExecution(ctx, def, fp, req); err != nil {
188					return Result{}, err
189				}
190				continue
191			}
192			if st.Fingerprint != fp {
193				return Result{}, ErrDefinitionConflict
194			}
195			if st.Terminal() {
196				return toResult(st), nil
197			}
198	
199			switch st.Status {
200			case StatusRunning:
201				advanced, err := e.advanceForward(ctx, def, req, st)
202				if err != nil {
203					return Result{}, err
204				}
205				if !advanced {
206					// 所有步骤均已确认成功，重新读取以取得 completed 终态。
207					snap2, err := e.store.LoadSnapshot(ctx, req.BusinessKey, req.IdempotencyKey)
208					if err != nil {
209						return Result{}, err
210					}
211					return toResult(snap2.State), nil
212				}
213			case StatusCompensating:
214				done, err := e.advanceCompensation(ctx, def, req, st)
215				if err != nil {
216					return Result{}, err
217				}
218				if done {
219					return e.finishFailed(ctx, req)
220				}
221			default:
222				return Result{}, ErrInvalidDefinition
223			}
224		}
225	}
226	
227	// createExecution 在一个原子事务中建立执行状态并追加 started 事件。
228	func (e *Engine) createExecution(ctx context.Context, def Definition, fp string, req ExecutionRequest) error {
229		return e.store.Commit(ctx, req.BusinessKey, req.IdempotencyKey, func(tx Tx) error {
230			if b, ok := tx.Binding(); ok && b.Fingerprint != fp {
231				return ErrDefinitionConflict
232			}
233			if tx.State() != nil {
234				return nil // 并发情况下已由其它调用建立，直接沿用
235			}
236			steps := make([]StepState, len(def.Steps))
237			for i, s := range def.Steps {
238				steps[i] = StepState{Name: s.Name}
239			}
240			tx.Create(&ExecutionState{
241				SagaName:    def.Name,
242				Fingerprint: fp,
243				Status:      StatusRunning,
244				Steps:       steps,
245				Payload:     req.Payload,
246			})
247			tx.AppendEvent(EventExecutionStarted, EventPayload{
248				SagaName:       def.Name,
249				IdempotencyKey: req.IdempotencyKey,
250				Status:         StatusRunning,
251			})
252			return nil
253		})
254	}
255	
256	// advanceForward 推进正向步骤：顺序模式（定义未声明任何前置）执行下一个
257	// 未完成步骤；依赖图模式按前置满足情况并发调度全部就绪步骤。
258	// 动作在事务外调用，成功/失败结果与事件原子提交。返回 false 表示已无待执行步骤。
259	//
260	// 步骤配置了 ActionRetry 时，动作在预算内失败会等待指定时长后再次调用同一
261	// 动作；中间失败既不提交状态也不追加事件。等待与动作都响应 ctx：ctx 取消
262	// 时直接返回其错误，本次不确认动作、不启动补偿，已提交的步骤状态保持不变。
263	func (e *Engine) advanceForward(ctx context.Context, def Definition, req ExecutionRequest, st *ExecutionState) (bool, error) {
264		if hasDeps(def) {
265			return e.graphForward(ctx, def, req, st)
266		}
267	
268		idx := -1
269		for i := range st.Steps {
270			if st.Steps[i].Status == "" {
271				idx = i
272				break
273			}
274		}
275		if idx < 0 {
276			return false, nil
277		}
278		step := def.Steps[idx]
279	
280		// Attempts 记录本阶段（含预算内重试）动作的实际调用次数，成功或预算
281		// 耗尽后随状态一次提交；未确认的中间失败不会留下任何计数。
282		startedAt := e.now()
283		actionErr, attempts, err := e.runWithRetry(ctx, step.ActionRetry, func() error {
284			return step.Action(ctx, execView{state: st, payload: req.Payload})
285		})
286		if err != nil {
287			// 调用方取消（等待期间或动作随 ctx 结束）：不解释为业务失败，
288			// 未确认的步骤留待后续同身份重试，已确认的提交状态不变。
289			return false, err
290		}
291		finishedAt := e.now()
292		st.Steps[idx].Attempts = attempts
293		st.Steps[idx].StartedAt = startedAt
294	
295		if err := e.commitStepResult(ctx, def, req, idx, startedAt, finishedAt, attempts, actionErr); err != nil {
296			return false, err
297		}
298		return true, nil
299	}
300	
301	// hasDeps 报告定义是否声明了任何前置关系：是则进入依赖图调度模式，
302	// 否则保持按声明顺序逐个执行的顺序模式。
303	func hasDeps(def Definition) bool {
304		for _, s := range def.Steps {
305			if len(s.DependsOn) > 0 {
306				return true
307			}
308		}
309		return false
310	}
311	
312	// graphForward 依赖图模式的正向调度：前置全部确认成功的步骤可启动，无前置
313	// 的步骤同时启动；某一步确认后立即检查并启动因此就绪的后续步骤。
314	//
315	// 任一步骤预算耗尽仍失败（或 ctx 取消、提交出错）时停止调度未启动步骤，
316	// 但已启动的兄弟动作会继续运行到返回并各自原子提交结果，随后本函数才返回。
317	// 返回 false 表示没有任何步骤需要启动（全部已确认）。
318	func (e *Engine) graphForward(ctx context.Context, def Definition, req ExecutionRequest, st *ExecutionState) (bool, error) {
319		index := make(map[string]int, len(def.Steps))
320		for i, s := range def.Steps {
321			index[s.Name] = i
322		}
323		deps := make([][]int, len(def.Steps))
324		for i, s := range def.Steps {
325			for _, d := range s.DependsOn {
326				deps[i] = append(deps[i], index[d])
327			}
328		}
329	
330		// local 是调度器私有的状态镜像：随各动作提交结果而更新，用于计算就绪
331		// 步骤与构造动作启动时刻的只读视图。只有本 goroutine 读写它，工作
332		// goroutine 拿到的是启动时刻的克隆，无需加锁。
333		local := cloneState(st)
334		launched := make([]bool, len(def.Steps))
335		for i := range local.Steps {
336			if local.Steps[i].Status != "" {
337				launched[i] = true // 已确认（成功/失败）的步骤不再进入
338			}
339		}
340	
341		type outcome struct {
342			idx       int
343			actionErr error // 预算耗尽后的业务错误；nil 表示确认成功
344			callErr   error // ctx 取消或状态提交失败
345		}
346		results := make(chan outcome, len(def.Steps))
347		inFlight := 0
348		launchedAny := false
349		halted := false // 失败/取消/出错后停止调度新步骤
350		var firstErr error
351	
352		for {
353			if !halted {
354				for i := range def.Steps {
355					if launched[i] {
356						continue
357					}
358					ready := true
359					for _, d := range deps[i] {
360						if local.Steps[d].Status != StepResultSucceeded {
361							ready = false
362							break
363						}
364					}
365					if !ready {
366						continue
367					}
368					launched[i] = true
369					launchedAny = true
370					inFlight++
371					view := cloneState(local)
372					go func(i int, view *ExecutionState) {
373						step := def.Steps[i]
374						startedAt := e.now()
375						actionErr, attempts, callErr := e.runWithRetry(ctx, step.ActionRetry, func() error {
376							return step.Action(ctx, execView{state: view, payload: req.Payload})
377						})
378						if callErr != nil {
379							results <- outcome{idx: i, callErr: callErr}
380							return
381						}
382						finishedAt := e.now()
383						if err := e.commitStepResult(ctx, def, req, i, startedAt, finishedAt, attempts, actionErr); err != nil {
384							results <- outcome{idx: i, callErr: err}
385							return
386						}
387						results <- outcome{idx: i, actionErr: actionErr}
388					}(i, view)
389				}
390			}
391			if inFlight == 0 {
392				break
393			}
394			r := <-results
395			inFlight--
396			switch {
397			case r.callErr != nil:
398				if firstErr == nil {
399					firstErr = r.callErr
400				}
401				halted = true
402			case r.actionErr != nil:
403				local.Steps[r.idx].Status = StepResultFailed
404				halted = true // 停止调度未启动步骤；已启动的兄弟动作继续跑完并提交
405			default:
406				local.Steps[r.idx].Status = StepResultSucceeded
407				local.SucceededOrder = append(local.SucceededOrder, local.Steps[r.idx].Name)
408			}
409		}
410		return launchedAny, firstErr
411	}
412	
413	// commitStepResult 把一个正向步骤的确认结果（成功或预算耗尽的失败）与对应
414	// 事件在同一个 Store 事务中原子提交。顺序与依赖图模式共用本函数。
415	func (e *Engine) commitStepResult(ctx context.Context, def Definition, req ExecutionRequest, idx int, startedAt, finishedAt time.Time, attempts int, actionErr error) error {
416		step := def.Steps[idx]
417		return e.store.Commit(ctx, req.BusinessKey, req.IdempotencyKey, func(tx Tx) error {
418			cur := tx.State()
419			if cur == nil || cur.Terminal() {
420				return nil // 状态已被其它路径推进，本次结果丢弃
421			}
422			cs := &cur.Steps[idx]
423			cs.Attempts = attempts
424			cs.StartedAt = startedAt
425			cs.FinishedAt = finishedAt
426	
427			if actionErr == nil {
428				cs.Status = StepResultSucceeded
429				cs.LastError = ""
430				cur.SucceededOrder = append(cur.SucceededOrder, step.Name)
431				succeeded := succeededNames(cur)
432				if allSucceeded(cur) {
433					cur.Status = StatusCompleted
434					tx.AppendEvent(EventStepSucceeded, stepEvent(def, req, step.Name, StatusCompleted, succeeded))
435					tx.AppendEvent(EventExecutionCompleted, EventPayload{
436						SagaName:       def.Name,
437						IdempotencyKey: req.IdempotencyKey,
438						Status:         StatusCompleted,
439						SucceededSteps: succeeded,
440					})
441				} else {
442					// 依赖图模式下兄弟步骤可能已失败：此时执行处于 compensating，
443					// 成功结果仍照常提交，执行状态保持 compensating 不变。
444					tx.AppendEvent(EventStepSucceeded, stepEvent(def, req, step.Name, cur.Status, succeeded))
445				}
446				return nil
447			}
448	
449			errMsg := actionErr.Error()
450			cs.Status = StepResultFailed
451			cs.LastError = errMsg
452			if cur.Status != StatusCompensating {
453				// 首个失败驱动执行转入补偿；并发的兄弟步骤随后也失败时只记录
454				// 该步自身的错误，不覆盖执行级失败信息。
455				cur.FailedStep = step.Name
456				cur.FailureReason = errMsg
457				cur.Status = StatusCompensating
458			}
459			tx.AppendEvent(EventStepFailed, EventPayload{
460				SagaName:       def.Name,
461				IdempotencyKey: req.IdempotencyKey,
462				Step:           step.Name,
463				Status:         StatusCompensating,
464				Reason:         errMsg,
465				SucceededSteps: succeededNames(cur),
466			})
467			return nil
468		})
469	}
470	
471	// runWithRetry 在重试预算内反复调用同一动作。
472	//
473	// 返回 actionErr 为 nil 表示预算内成功（调用次数计入 attempts）；
474	// actionErr 非 nil、err 为 nil 表示预算耗尽仍失败（或失败被 Permanent
475	// 标记为永久失败），actionErr 为最近一次错误；
476	// err 非 nil 表示外层 context 已取消——可能发生在调用前、失败后的等待期间，
477	// 也可能动作刚返回（无论它返回 nil 还是错误），只要外层 context 已取消就
478	// 按取消处理：不确认动作，由调用方原样返回 ctx 错误。
479	//
480	// 永久失败优先于重试预算：动作返回 Permanent 包装的错误时，即使仍有剩余
481	// 次数也立即结束本阶段、不再等待，但 context 取消仍优先于永久失败。
482	func (e *Engine) runWithRetry(ctx context.Context, policy RetryPolicy, call func() error) (actionErr error, attempts int, err error) {
483		budget := normalizeRetry(policy)
484		for {
485			if err := ctx.Err(); err != nil {
486				return nil, attempts, err
487			}
488			attempts++
489			actionErr = call()
490			// 与基线一致：动作返回后先看外层 context，已取消则即使动作报告成功
491			// 或永久失败也不确认该动作——结果可能已在下游生效，由同身份重入依赖
492			// 动作幂等收敛。
493			if err := ctx.Err(); err != nil {
494				return nil, attempts, err
495			}
496			if actionErr == nil {
497				return nil, attempts, nil
498			}
499			// 永久失败：业务上已明确不可能成功，即使预算尚有剩余也不再等待、
500			// 不再调用，按与预算耗尽相同的口径交由调用方提交。
501			if IsPermanent(actionErr) {
502				return actionErr, attempts, nil
503			}
504			if attempts >= budget.maxAttempts {
505				return actionErr, attempts, nil
506			}
507			// 仍有剩余次数：等待指定时长后再次调用同一动作，等待响应 context。
508			if budget.wait > 0 {
509				t := time.NewTimer(budget.wait)
510				select {
511				case <-ctx.Done():
512					t.Stop()
513					return nil, attempts, ctx.Err()
514				case <-t.C:
515				}
516			}
517		}
518	}
519	
520	// advanceCompensation 按确认成功顺序的逆序补偿下一个已确认成功的步骤。
521	// 返回 done=true 表示已无待补偿步骤，调用方应把执行收束为 failed 终态。
522	// 补偿动作返回错误时，执行在同一事务中固定为 compensation_failed 终态。
523	func (e *Engine) advanceCompensation(ctx context.Context, def Definition, req ExecutionRequest, st *ExecutionState) (bool, error) {
524		// 确认顺序的逆序：最后确认成功的步骤最先补偿。顺序模式下确认顺序即
525		// 声明顺序，与此前按声明逆序补偿的行为一致。
526		succeeded := succeededNames(st)
527		idx := -1
528		if len(succeeded) > 0 {
529			target := succeeded[len(succeeded)-1]
530			for i := range st.Steps {
531				if st.Steps[i].Name == target {
532					idx = i
533					break
534				}
535			}
536		}
537		if idx < 0 {
538			return true, nil
539		}
540		step := def.Steps[idx]
541	
542		// 未配置补偿动作的步骤视为补偿成功，不计数、不记录补偿时间。
543		var compErr error
544		var attempts int
545		var compensatedAt time.Time
546		if step.Compensate != nil {
547			// CompensationAttempts 记录本阶段（含预算内重试）补偿的实际调用次数，
548			// 成功或预算耗尽后随状态一次提交；中间失败不留计数、不追加事件。
549			var callErr error
550			compErr, attempts, callErr = e.runWithRetry(ctx, step.CompensateRetry, func() error {
551				return step.Compensate(ctx, execView{state: st, payload: req.Payload})
552			})
553			if callErr != nil {
554				return false, callErr
555			}
556			compensatedAt = e.now()
557			st.Steps[idx].CompensationAttempts = attempts
558		}
559	
560		err := e.store.Commit(ctx, req.BusinessKey, req.IdempotencyKey, func(tx Tx) error {
561			cur := tx.State()
562			if cur == nil || cur.Terminal() {
563				return nil
564			}
565			cs := &cur.Steps[idx]
566			if step.Compensate != nil {
567				cs.CompensationAttempts = attempts
568				cs.CompensatedAt = compensatedAt
569			}
570	
571			if compErr == nil {
572				cs.Status = StepResultCompensated
573				cs.LastError = ""
574				cur.Status = StatusCompensating
575				tx.AppendEvent(EventStepCompensated, EventPayload{
576					SagaName:       def.Name,
577					IdempotencyKey: req.IdempotencyKey,
578					Step:           step.Name,
579					Status:         StatusCompensating,
580				})
581				return nil
582			}
583	
584			errMsg := compErr.Error()
585			cs.Status = StepResultCompensationFailed
586			cs.LastError = errMsg
587			cur.FailedCompensationStep = step.Name
588			cur.CompensationError = errMsg
589			cur.Status = StatusCompensationFailed
590			tx.AppendEvent(EventStepCompensationFailed, EventPayload{
591				SagaName:       def.Name,
592				IdempotencyKey: req.IdempotencyKey,
593				Step:           step.Name,
594				Status:         StatusCompensationFailed,
595				Reason:         errMsg,
596				Attempt:        cs.CompensationAttempts,
597			})
598			tx.AppendEvent(EventCompensationFailed, EventPayload{
599				SagaName:       def.Name,
600				IdempotencyKey: req.IdempotencyKey,
601				Step:           step.Name,
602				Status:         StatusCompensationFailed,
603				Reason:         errMsg,
604			})
605			return nil
606		})
607		if err != nil {
608			return false, err
609		}
610		return false, nil
611	}
612	
613	// finishFailed 在补偿全部完成后把执行收束为 failed 终态并返回结果。
614	func (e *Engine) finishFailed(ctx context.Context, req ExecutionRequest) (Result, error) {
615		err := e.store.Commit(ctx, req.BusinessKey, req.IdempotencyKey, func(tx Tx) error {
616			cur := tx.State()
617			if cur == nil || cur.Terminal() {
618				return nil
619			}
620			cur.Status = StatusFailed
621			tx.AppendEvent(EventExecutionFailed, EventPayload{
622				SagaName:       cur.SagaName,
623				IdempotencyKey: req.IdempotencyKey,
624				Status:         StatusFailed,
625				Step:           cur.FailedStep,
626				Reason:         cur.FailureReason,
627			})
628			return nil
629		})
630		if err != nil {
631			return Result{}, err
632		}
633		snap, err := e.store.LoadSnapshot(ctx, req.BusinessKey, req.IdempotencyKey)
634		if err != nil {
635			return Result{}, err
636		}
637		return toResult(snap.State), nil
638	}
639	
640	// succeededNames 返回当前仍为成功状态的步骤名，按确认成功的先后顺序排列。
641	// 旧版本写入的状态没有确认顺序记录，回退为声明顺序（与当时的确认顺序一致）。
642	func succeededNames(st *ExecutionState) []string {
643		if len(st.SucceededOrder) == 0 {
644			var names []string
645			for _, s := range st.Steps {
646				if s.Status == StepResultSucceeded {
647					names = append(names, s.Name)
648				}
649			}
650			return names
651		}
652		status := make(map[string]string, len(st.Steps))
653		for _, s := range st.Steps {
654			status[s.Name] = s.Status
655		}
656		var names []string
657		for _, n := range st.SucceededOrder {
658			if status[n] == StepResultSucceeded {
659				names = append(names, n)
660			}
661		}
662		return names
663	}
664	
665	// allSucceeded 报告全部步骤是否均已确认成功。
666	func allSucceeded(st *ExecutionState) bool {
667		for _, s := range st.Steps {
668			if s.Status != StepResultSucceeded {
669				return false
670			}
671		}
672		return true
673	}
674	
675	func stepEvent(def Definition, req ExecutionRequest, step, status string, succeeded []string) EventPayload {
676		return EventPayload{
677			SagaName:       def.Name,
678			IdempotencyKey: req.IdempotencyKey,
679			Step:           step,
680			Status:         status,
681			SucceededSteps: succeeded,
682		}
683	}
684	
685	func toResult(st *ExecutionState) Result {
686		outcomes := make([]StepOutcome, len(st.Steps))
687		for i, s := range st.Steps {
688			r := s.Status
689			if r == "" {
690				r = StepResultPending
691			}
692			outcomes[i] = StepOutcome{
693				Name:                 s.Name,
694				Result:               r,
695				Attempts:             s.Attempts,
696				CompensationAttempts: s.CompensationAttempts,
697				Error:                s.LastError,
698				StartedAt:            s.StartedAt,
699				FinishedAt:           s.FinishedAt,
700			}
701		}
702		return Result{
703			BusinessKey:            st.BusinessKey,
704			SagaName:               st.SagaName,
705			IdempotencyKey:         st.IdempotencyKey,
706			Status:                 st.Status,
707			FailureReason:          st.FailureReason,
708			CompensationError:      st.CompensationError,
709			FailedStep:             st.FailedStep,
710			FailedCompensationStep: st.FailedCompensationStep,
711			Steps:                  outcomes,
712			Terminal:               st.Terminal(),
713		}
714	}
715	
716	// GetResult 查询某执行身份的当前结果，不执行任何动作。
717	// 未知执行身份（或 sagaName 与该执行的定义名不符）返回 ErrExecutionNotFound。
718	func (e *Engine) GetResult(ctx context.Context, sagaName, businessKey, idempotencyKey string) (Result, error) {
719		if strings.TrimSpace(sagaName) == "" || strings.TrimSpace(businessKey) == "" || strings.TrimSpace(idempotencyKey) == "" {
720			return Result{}, ErrInvalidDefinition
721		}
722		snap, err := e.store.LoadSnapshot(ctx, businessKey, idempotencyKey)
723		if err != nil {
724			return Result{}, err
725		}
726		if snap.State == nil || snap.State.SagaName != sagaName {
727			return Result{}, ErrExecutionNotFound
728		}
729		return toResult(snap.State), nil
730	}
