type permanentError struct {
	err error
}

// Permanent 把 err 包装为永久失败，表明动作在业务上已明确不可能成功，
// 重试不会改变结果。
//
// 被包装的错误在重试预算中立即终止当前动作的重试阶段（不再等待、不再
