func TestGraphModeConcurrentCommits(t *testing.T) {
	dir := t.TempDir()
	store := openStore(t, dir)
	engine := txsaga.NewEngine(store)

	var mu sync.Mutex
	started := map[string]bool{}
	action := func(name string) txsaga.ActionFunc {
